package io.github.diodeme.ji.session.jsonl;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import io.github.diodeme.ji.ai.ModelRef;
import java.io.IOException;
import java.nio.file.Files;
import java.time.Instant;
import org.junit.jupiter.api.Test;

final class JsonlSessionRepositoryTest {
    @Test
    void rejectsTruncatedRevisionInsteadOfSilentlyFallingBack() throws IOException {
        var root = Files.createTempDirectory("ji-jsonl-corrupt-");
        var repository = new JsonlSessionRepository(root);
        repository.create("session-1", new ModelRef("faux", "model"), "workspace", Instant.EPOCH);
        Files.writeString(root.resolve("session-1.jsonl"), "{\"formatVersion\":1", java.nio.file.StandardOpenOption.APPEND);

        assertThrows(IllegalStateException.class, () -> repository.load("session-1"));
    }

    @Test
    void reopensAllCommittedRevisions() throws IOException {
        var root = Files.createTempDirectory("ji-jsonl-reopen-");
        var first = new JsonlSessionRepository(root);
        first.create("session-1", new ModelRef("faux", "model"), "workspace", Instant.EPOCH);
        first.update("session-1", 0, document -> document.setName(java.util.Optional.of("Example")));

        var reopened = new JsonlSessionRepository(root);
        assertEquals("Example", reopened.load("session-1").orElseThrow().name().orElseThrow());
        assertEquals(1, reopened.load("session-1").orElseThrow().revision());
    }
}
